/*
 * Minimal LVGL9-compatible font shim for the host simulator build. It exists
 * so pet_p4_font_cn.c (152k lines of fmt_txt glyph data, generated by
 * lv_font_conv) and pet_p4_renderer.c (lv_font glyph lookups) compile without
 * the real LVGL tree. Struct layouts and lookup semantics mirror
 * lvgl/src/font/{lv_font.h, fmt_txt/lv_font_fmt_txt.c} at 9.5, including the
 * 1/16 px advance units and class-based kerning.
 */
#ifndef PET_HOST_LVGL_SHIM_H
#define PET_HOST_LVGL_SHIM_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

#define LVGL_VERSION_MAJOR 9
#define LVGL_VERSION_MINOR 2
#define LV_VERSION_CHECK(x, y, z) \
  ((LVGL_VERSION_MAJOR > (x)) || \
   (LVGL_VERSION_MAJOR == (x) && LVGL_VERSION_MINOR > (y)))

#define LV_ATTRIBUTE_LARGE_CONST
#define LV_FONT_SUBPX_NONE 0

/* ---- glyph formats (values match lv_font_glyph_format_t) ---- */

enum {
  LV_FONT_GLYPH_FORMAT_NONE = 0x00,
  LV_FONT_GLYPH_FORMAT_A1 = 0x01,
  LV_FONT_GLYPH_FORMAT_A2 = 0x02,
  LV_FONT_GLYPH_FORMAT_A4 = 0x04,
  LV_FONT_GLYPH_FORMAT_A8 = 0x08,
};

/* ---- public font types ---- */

typedef struct _lv_font_t lv_font_t;

typedef struct {
  const lv_font_t *resolved_font;
  uint16_t adv_w;
  uint16_t box_w;
  uint16_t box_h;
  int16_t ofs_x;
  int16_t ofs_y;
  uint16_t stride;
  uint8_t format;
  uint8_t is_placeholder;
  uint8_t req_raw_bitmap;
  int32_t outline_stroke_width;
  union {
    uint32_t index;
    const void *src;
  } gid;
  void *entry;
} lv_font_glyph_dsc_t;

struct _lv_font_t {
  bool (*get_glyph_dsc)(const lv_font_t *, lv_font_glyph_dsc_t *,
                        uint32_t letter, uint32_t letter_next);
  const void *(*get_glyph_bitmap)(lv_font_glyph_dsc_t *, void *);
  void (*release_glyph)(const lv_font_t *, lv_font_glyph_dsc_t *);
  int32_t line_height;
  int32_t base_line;
  uint8_t subpx;
  uint8_t kerning;
  uint8_t static_bitmap;
  int8_t underline_position;
  int8_t underline_thickness;
  const void *dsc;
  const lv_font_t *fallback;
  void *user_data;
};

/* ---- fmt_txt database types ---- */

typedef struct {
  uint32_t bitmap_index;
  uint32_t adv_w;
  int8_t box_w;
  int8_t box_h;
  int8_t ofs_x;
  int8_t ofs_y;
} lv_font_fmt_txt_glyph_dsc_t;

enum {
  LV_FONT_FMT_TXT_CMAP_FORMAT0_TINY = 0,
  LV_FONT_FMT_TXT_CMAP_FORMAT0_FULL = 1,
  LV_FONT_FMT_TXT_CMAP_SPARSE_TINY = 2,
  LV_FONT_FMT_TXT_CMAP_SPARSE_FULL = 3,
};

typedef struct {
  uint32_t range_start;
  uint32_t range_length;
  uint32_t glyph_id_start;
  const uint16_t *unicode_list;
  const void *glyph_id_ofs_list;
  uint16_t list_length;
  uint8_t type;
} lv_font_fmt_txt_cmap_t;

typedef struct {
  const int8_t *class_pair_values;
  const uint8_t *left_class_mapping;
  const uint8_t *right_class_mapping;
  uint8_t left_class_cnt;
  uint8_t right_class_cnt;
} lv_font_fmt_txt_kern_classes_t;

typedef struct {
  const uint8_t *glyph_bitmap;
  const lv_font_fmt_txt_glyph_dsc_t *glyph_dsc;
  const lv_font_fmt_txt_cmap_t *cmaps;
  const void *kern_dsc;
  uint16_t kern_scale;
  uint16_t cmap_num;
  uint8_t bpp;
  uint8_t kern_classes;
  uint16_t bitmap_format : 2;
  uint8_t stride;
} lv_font_fmt_txt_dsc_t;

/* ---- lookup engine ---- */

bool lv_font_get_glyph_dsc_fmt_txt(const lv_font_t *font,
                                   lv_font_glyph_dsc_t *dsc_out,
                                   uint32_t unicode_letter,
                                   uint32_t unicode_letter_next);
const void *lv_font_get_bitmap_fmt_txt(lv_font_glyph_dsc_t *g_dsc, void *draw_buf);
bool lv_font_get_glyph_dsc(const lv_font_t *font, lv_font_glyph_dsc_t *dsc_out,
                           uint32_t letter, uint32_t letter_next);
void lv_font_glyph_release_draw_data(lv_font_glyph_dsc_t *g_dsc);

#endif /* PET_HOST_LVGL_SHIM_H */
